// The ship meter's quiet figure (show-quiet-time-and-reset-the-meter-on-clear
// design D3): how long a live run has gone without activity, and the word the
// meter shows once that reaches the published threshold.
//
// Pure and Node-free: `hooks/mod.mjs` imports it inside the engine, where there
// is no Node, and `test/spine/mod-pins.test.mjs` walks the import. The two
// numbers are `interlock limits`'s; neither this file nor the hooks module
// restates them. The word names no cause: a run waiting on a plan window and a
// run that hung read the same here, and the person tells them apart from the
// windows the pane lists beside it.

import { LIMITS } from './limits.mjs'

const MINUTE_MS = 60 * 1000

/** The period of the meter's interval, in milliseconds. */
export const TICK_MS = LIMITS.meterTickMs

/**
 * Milliseconds from the last activity to now, never negative (a clock that went
 * backwards reads as no wait). `null` unless both are finite numbers: a time
 * the module could not read is no figure, never a guessed one.
 *
 * @param {unknown} lastActivityAt milliseconds since the epoch, or null
 * @param {unknown} now milliseconds since the epoch, or null
 * @returns {number|null}
 */
export function quietMs(lastActivityAt, now) {
  if (!Number.isFinite(lastActivityAt) || !Number.isFinite(now)) return null
  return Math.max(0, now - lastActivityAt)
}

/**
 * `quiet <n> min` once `ms` reaches the threshold, `<n>` the whole minutes and
 * `<1` under one; `null` below it, or for no figure.
 *
 * @param {number|null} ms what `quietMs` returned
 * @param {number} [afterMs] the threshold; the published one unless a test names another
 * @returns {string|null}
 */
export function quietWord(ms, afterMs = LIMITS.meterQuietAfterMs) {
  if (!Number.isFinite(ms) || ms < afterMs) return null
  const minutes = Math.floor(ms / MINUTE_MS)
  return `quiet ${minutes < 1 ? '<1' : minutes} min`
}

files.lib/meter-time.mjs:
// The ship meter's time words: the clock reading a line was stamped with, and
// how long a turn took, as a person reads them.
//
// Each reading is the engine's own (`$.clock.now()` in the hooks module), so a
// time is either a real reading or absent: absent draws as nothing, never as a
// guessed time. The wall-clock words are the local time of the machine the
// engine runs on, from `Date`'s own local fields. The duration bands are unit
// conversions (seconds, minutes, hours), not thresholds: no band is a verdict
// on the figure it formats.
//
// Pure and Node-free: the hooks module runs in the engine with no Node, and
// imports this file.

const isTime = ms => typeof ms === 'number' && Number.isFinite(ms)
const pad = n => String(n).padStart(2, '0')

/** The local wall-clock time of a reading, `HH:MM:SS`; `''` for no reading. */
export function clockText(ms) {
  if (!isTime(ms)) return ''
  const d = new Date(ms)
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`
}

/** The local date and time of a reading, `YYYY-MM-DD HH:MM:SS`; `''` for no reading. */
export function stampText(ms) {
  if (!isTime(ms)) return ''
  const d = new Date(ms)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${clockText(ms)}`
}

/**
 * A duration in milliseconds as a person reads it: under a minute, seconds to
 * one decimal, cut down (`41.2s`, `0.8s`, never `60.0s`); under an hour, whole
 * minutes and seconds (`2m 14s`); else hours and minutes (`1h 03m`). `''` for
 * no figure, a negative one or one that is not a finite number.
 */
export function durationText(ms) {
  if (!isTime(ms) || ms < 0) return ''
  if (ms < 60_000) return `${(Math.floor(ms / 100) / 10).toFixed(1)}s`
  const seconds = Math.floor(ms / 1000)
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${pad(seconds % 60)}s`
  return `${Math.floor(seconds / 3600)}h ${pad(Math.floor((seconds % 3600) / 60))}m`
}

files.lib/meter-timeline.mjs:
// The ship meter's step timeline: what each step the CLI printed says, and the
// order the pane lays the steps, the agents they spawned and the agents no
// step names in.
//
// A step's words are its own fields, verbatim: the action, its position, how
// many lanes a batch dispatched, a skipped verification's reason, a halt's
// reason and the plan size a step relayed. No word here is a verdict, a cause
// or a state the step did not carry.
//
// The order is pure data over plain inputs, so it is pinned under Node
// (`test/spine/meter-timeline.test.mjs`) and the hooks module only draws it:
//
// - The top level is the launch, every step and every relay agent no step
//   names, laid by time. An entry with a time sorts by it, ties keeping their
//   input order (the launch, then the steps as they crossed, then the relays as
//   first seen); an entry with no time follows every timed one, in input order.
// - Beneath a step, at depth 1, the agents it spawned: a spawn is joined to an
//   agent by its briefing hash, one agent per spawn in step order (an agent
//   beyond the spawns that carry its hash stays with the last of them). The
//   joined spawns are laid by their agent's first request time, by the same
//   rule; the spawns no agent has joined yet follow, `waiting`, in the step's
//   spawn order. A step's relay is drawn on the step's own line and nowhere
//   else.
// - Last, the agents nothing names, under one head, in first-seen order.
//
// Pure and Node-free: the hooks module runs in the engine with no Node, and
// imports this file.

/** The actions that dispatch a batch of lanes. */
export const BATCH_ACTIONS = new Set(['run-batch', 'test-wave'])

const isInt = v => Number.isInteger(v)
const isTime = v => typeof v === 'number' && Number.isFinite(v)
const str = v => (typeof v === 'string' && v ? v : null)
const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`

/** `batch <j>/<k>`, one-based, as the status line says it; `null` when the step carries no position. */
export function batchText(batchIndex, batchCount) {
  return isInt(batchIndex) && isInt(batchCount) ? `batch ${batchIndex + 1}/${batchCount}` : null
}

/** How many lanes run side by side: `N in parallel`, `1 lane`, or `null` for none. */
export function laneCountText(n) {
  if (!isInt(n) || n < 1) return null
  return n === 1 ? '1 lane' : `${n} in parallel`
}

/** The waves a plan summary holds, its test wave counted; `null` for anything that is not a summary. */
export function planWaveCount(plan) {
  if (plan === null || typeof plan !== 'object' || !Array.isArray(plan.waves)) return null
  return plan.waves.length + (plan.testWave ? 1 : 0)
}

/** A step's words, from its own fields only. */
export function stepText(step) {
  const s = step && typeof step === 'object' ? step : {}
  const parts = [String(s.action)]
  if (s.wave !== undefined && s.wave !== null) parts.push(`wave ${s.wave}`)
  const batch = batchText(s.batchIndex, s.batchCount)
  if (batch) parts.push(batch)
  if (BATCH_ACTIONS.has(s.action)) {
    const lanes = laneCountText(Array.isArray(s.spawns) ? s.spawns.length : 0)
    if (lanes) parts.push(lanes)
  }
  if (s.action === 'verify' && s.skipped === true) parts.push(str(s.reason) ? `skipped: ${s.reason}` : 'skipped')
  if (s.action === 'halt' && str(s.reason)) parts.push(s.reason)
  if (isInt(s.planWaves)) parts.push(`plan: ${plural(s.planWaves, 'wave')}`)
  return parts.join(' · ')
}

/** The entries with a time laid by it, ties in input order; then the entries with none, in input order. */
function byTime(entries) {
  const timed = entries.map((entry, i) => ({ entry, i })).filter(({ entry }) => isTime(entry.at))
  timed.sort((a, b) => a.entry.at - b.entry.at || a.i - b.i)
  return [...timed.map(({ entry }) => entry), ...entries.filter(entry => !isTime(entry.at))]
}

/**
 * The timeline as ordered display entries, each `{ key, kind, at, depth, ... }`:
 * `launch` (`name`), `step` (`step`), `spawn` (`step`, `spawn`, `agent` or
 * `null` while it waits), `relay` (`agent`, a relay agent no step names),
 * `unmatched-head`, and `unmatched` (`agent`). An agent's entry is keyed
 * `agent-<id>`, a waiting spawn's `spawn-<n>-<label>`, a step's `step-<n>`.
 *
 * @param {{
 *   steps?: {n: number, at: number|null, action: string, wave?: unknown, waveIndex?: unknown, batchIndex?: unknown,
 *     batchCount?: unknown, skipped?: unknown, reason?: unknown, planWaves?: number|null, relayId?: string|null,
 *     spawns: {label: string, title: string, sha: string|null}[]}[],
 *   agents?: {id: string, sha?: string|null, relay?: string|null, firstAt?: number|null}[],
 *   launch?: {at: number|null, name?: string|null}|null
 * }} input
 * @returns {object[]}
 */
export function timeline({ steps = [], agents = [], launch = null } = {}) {
  const relays = new Set(steps.map(step => str(step.relayId)).filter(Boolean))

  // Each spawn carrying a hash, in step order, and the agents carrying it, first seen first.
  const slots = new Map()
  const spawnsOf = step => (Array.isArray(step.spawns) ? step.spawns : [])
  steps.forEach((step, i) =>
    spawnsOf(step).forEach((spawn, j) => {
      const sha = str(spawn.sha)
      if (!sha) return
      if (!slots.has(sha)) slots.set(sha, [])
      slots.get(sha).push({ pos: `${i}:${j}`, agents: [] })
    })
  )
  const placed = new Set()
  const counts = new Map()
  for (const agent of agents) {
    const sha = str(agent.sha)
    if (!sha || relays.has(agent.id) || !slots.has(sha)) continue
    const held = slots.get(sha)
    const at = counts.get(sha) || 0
    held[Math.min(at, held.length - 1)].agents.push(agent)
    counts.set(sha, at + 1)
    placed.add(agent.id)
  }
  const joinedBy = new Map()
  for (const held of slots.values()) for (const slot of held) joinedBy.set(slot.pos, slot.agents)

  const top = []
  if (launch && typeof launch === 'object') {
    top.push({ key: 'launch', kind: 'launch', at: isTime(launch.at) ? launch.at : null, depth: 0, name: str(launch.name) })
  }
  for (const step of steps) top.push({ key: `step-${step.n}`, kind: 'step', at: isTime(step.at) ? step.at : null, depth: 0, step })
  const orphans = agents.filter(agent => str(agent.relay) && !relays.has(agent.id) && !placed.has(agent.id))
  for (const agent of orphans) {
    top.push({ key: `agent-${agent.id}`, kind: 'relay', at: isTime(agent.firstAt) ? agent.firstAt : null, depth: 0, agent })
    placed.add(agent.id)
  }

  const out = []
  for (const entry of byTime(top)) {
    out.push(entry)
    if (entry.kind !== 'step') continue
    const i = steps.indexOf(entry.step)
    const joined = []
    const waiting = []
    for (const [j, spawn] of spawnsOf(entry.step).entries()) {
      const held = joinedBy.get(`${i}:${j}`) || []
      if (!held.length) {
        waiting.push({ key: `spawn-${entry.step.n}-${spawn.label}`, kind: 'spawn', at: null, depth: 1, step: entry.step, spawn, agent: null })
      }
      for (const agent of held) {
        const at = isTime(agent.firstAt) ? agent.firstAt : null
        joined.push({ key: `agent-${agent.id}`, kind: 'spawn', at, depth: 1, step: entry.step, spawn, agent })
      }
    }
    out.push(...byTime(joined), ...waiting)
  }

  const unmatched = agents.filter(agent => !relays.has(agent.id) && !placed.has(agent.id))
  if (unmatched.length) {
    out.push({ key: 'agents-unmatched-head', kind: 'unmatched-head', at: null, depth: 0 })
    for (const agent of unmatched) {
      out.push({ key: `agent-${agent.id}`, kind: 'unmatched', at: isTime(agent.firstAt) ? agent.firstAt : null, depth: 1, agent })
    }
  }
  return out
}

files.lib/meter-refusals.mjs:
// The ship meter's refusal words (speak-permission-prompts-and-guard-denials
// design D4-D6): the four guard names a settings guard's denial is read by,
// the slice of an errored result's text the meter repeats, and the pane lines.
//
// Pure and Node-free: `hooks/mod.mjs` imports it inside the engine, where there
// is no Node, and `test/spine/mod-pins.test.mjs` walks the import and pins the
// names against the four guards' own `GUARD` constants. Nothing here judges a
// denial: the words are the guard's, and the ruling is `lib/launch-rule.mjs`'s.

/** The settings guards whose denials the meter repeats, as each prints its name. */
export const GUARD_NAMES = Object.freeze(['guard-tests', 'guard-tasks', 'guard-commit', 'guard-relaunch'])

// Anywhere in the text, not only at its start: the engine puts
// `PreToolUse:<tool> hook error: ` in front of a settings hook's reason (probe 2).
const NAMED = new RegExp(`\\b(${GUARD_NAMES.join('|')}): `)

/**
 * The text from the first guard name on, or `null` for a text that names no
 * guard (another plugin's deny, a command that failed) or is not a string.
 *
 * @param {unknown} text an errored tool result's `text`
 * @returns {string|null}
 */
export function guardReason(text) {
  if (typeof text !== 'string') return null
  const m = NAMED.exec(text)
  return m ? text.slice(m.index) : null
}

/**
 * The guard that spoke `reason`, as `guardReason` sliced it; `null` for none.
 *
 * @param {unknown} reason
 * @returns {string|null}
 */
export function guardOf(reason) {
  if (typeof reason !== 'string') return null
  const m = NAMED.exec(reason)
  return m && m.index === 0 ? m[1] : null
}

/**
 * `guard denials: <n> (<guard> <n>, …)` in the order each guard was first
 * seen, or `null` when none was: the pane draws no line for nothing.
 *
 * @param {Map<string, number>|undefined} counts
 * @returns {string|null}
 */
export function guardDenialLine(counts) {
  if (!(counts instanceof Map) || counts.size === 0) return null
  let total = 0
  const parts = []
  for (const [guard, n] of counts) {
    total += n
    parts.push(`${guard} ${n}`)
  }
  return `guard denials: ${total} (${parts.join(', ')})`
}

/**
 * The launch guard's current ruling over the session's record, in the rule's
 * own words. `now` is `null` only when the guard's facts could not be read,
 * which allows the next launch (design D5).
 *
 * @param {{ decision: string, reason: string|null }} ruling what `decideLaunch` returned
 * @param {number|null} now
 * @returns {string}
 */
export function launchGuardLine(ruling, now) {
  if (now === null) return 'launch guard: facts unreadable; the next launch is allowed'
  if (ruling && ruling.decision === 'deny' && ruling.reason) return `launch guard: next launch refused: ${ruling.reason}`
  return 'launch guard: next launch allowed'
}

files.lib/preflight-file.mjs:
// The session start's report file: what `hooks/preflight.mjs` leaves in
// `.claude/ship/preflight.json`, and every line the hooks module draws from it
// (show-preflight-and-interrupted-runs-at-session-start design D1, D5-D8).
//
// Two readers of one shape. The hook builds the report from what it already
// holds: the doctor's verdict and checks, the interrupted-run notes it spoke
// and marked, the halt resume cards it listed. The hooks module reads it at a
// prompt the person submits and draws the `AbovePrompt` band and two panes.
// Neither side derives a fact the other did not say: every word drawn is the
// doctor's, the hook's or the card's, and the time is a date, never a
// staleness verdict.
//
// Node-free, and importing only `./limits.mjs`, because the hooks module runs
// in the engine with no Node (test/spine/mod-pins.test.mjs walks it). The
// handoff pane's cap is read here and restated nowhere in the module.

import { LIMITS } from './limits.mjs'

/** Bump when the report's shape changes, so a reader can tell an older one. */
export const PREFLIGHT_SCHEMA = 'interlock.preflight/1'

/** Where the report lands, relative to the working root. Already gitignored with `.claude/ship/`. */
export const PREFLIGHT_FILE = '.claude/ship/preflight.json'

/** The most characters of a card the handoff pane renders: the `Markdown` element's own bound (design D7). */
export const HANDOFF_PANE_CHARS = LIMITS.handoffPaneChars

/** The SessionStart sources the host names; anything else is recorded as null. */
const SOURCES = new Set(['startup', 'resume', 'clear', 'compact'])

const str = v => (typeof v === 'string' && v ? v : null)
const text = v => (typeof v === 'string' ? v : v === null || v === undefined ? '' : String(v))
const list = v => (Array.isArray(v) ? v.filter(x => x && typeof x === 'object') : [])
const count = v => (Number.isInteger(v) && v >= 0 ? v : 0)

/** The report file's path under `cwd`, or the relative path the engine resolves under the session's directory. */
export function preflightFilePath(cwd) {
  if (typeof cwd !== 'string' || !cwd) return PREFLIGHT_FILE
  return `${cwd.endsWith('/') ? cwd.slice(0, -1) : cwd}/${PREFLIGHT_FILE}`
}

function doctorOf(d) {
  const doctor = d && typeof d === 'object' ? d : {}
  const counts =
    doctor.counts && typeof doctor.counts === 'object'
      ? Object.fromEntries(['ok', 'warn', 'fail', 'skip'].map(k => [k, count(doctor.counts[k])]))
      : null
  return {
    ran: doctor.ran === true,
    parsed: doctor.parsed === true,
    ok: typeof doctor.ok === 'boolean' ? doctor.ok : null,
    counts,
    // `evidence` is not copied: no reader draws it, and the module reads the file whole.
    checks: list(doctor.checks).map(c => ({ id: text(c.id), status: text(c.status), detail: text(c.detail), fix: str(c.fix) }))
  }
}

function notesOf(n) {
  const notes = n && typeof n === 'object' ? n : {}
  return {
    spoken: list(notes.spoken).map(s => ({
      runId: text(s.runId),
      change: str(s.change),
      stage: str(s.stage),
      banner: text(s.banner),
      marked: s.marked === true,
      marks: list(s.marks).map(m => ({ root: text(m.root), marked: m.marked === true, reason: str(m.reason) }))
    })),
    unreadable: list(notes.unreadable).map(u => ({ file: text(u.file), reason: text(u.reason) }))
  }
}

function cardsOf(c) {
  const cards = c && typeof c === 'object' ? c : {}
  return {
    listed: list(cards.listed).map(k => ({ path: text(k.path), change: text(k.change), runId: text(k.runId), writtenAt: str(k.writtenAt) })),
    archived: count(cards.archived),
    unreadable: list(cards.unreadable).map(u => ({ path: text(u.path), reason: text(u.reason) })),
    lookedIn: Array.isArray(cards.lookedIn) ? cards.lookedIn.filter(d => typeof d === 'string' && d) : []
  }
}

/**
 * The report, every field present: an absent fact is `null` or `[]`, never
 * omitted (design D1). Pure: the caller passes the time it wrote at.
 */
export function buildPreflightReport(input) {
  const i = input && typeof input === 'object' ? input : {}
  return {
    schema: PREFLIGHT_SCHEMA,
    writtenAt: str(i.writtenAt),
    source: SOURCES.has(i.source) ? i.source : null,
    root: str(i.root),
    stateHome: str(i.stateHome),
    surface: str(i.surface),
    message: typeof i.message === 'string' ? i.message : null,
    doctor: doctorOf(i.doctor),
    notes: notesOf(i.notes),
    cards: cardsOf(i.cards)
  }
}

/** `{ report }` from the file's text, or `{ problem }` naming why there is none. */
export function readPreflightReport(raw) {
  if (typeof raw !== 'string') return { problem: `not text: the read returned ${raw === null ? 'null' : typeof raw}` }
  let value
  try {
    value = JSON.parse(raw)
  } catch (err) {
    return { problem: `not JSON: ${(err && err.message) || err}` }
  }
  if (!value || typeof value !== 'object' || Array.isArray(value)) return { problem: 'not an object' }
  if (value.schema !== PREFLIGHT_SCHEMA) return { problem: `stamped ${JSON.stringify(value.schema)}, not ${PREFLIGHT_SCHEMA}` }
  return { report: buildPreflightReport(value) }
}

const flagged = report => report.doctor.checks.filter(c => c.status === 'fail' || c.status === 'warn')

/** Whether the band has anything to say: a fail or warn check, a doctor that did not run or parse, a spoken note, a card. */
export function shouldDraw(report) {
  return (
    flagged(report).length > 0 ||
    !report.doctor.ran ||
    !report.doctor.parsed ||
    report.notes.spoken.length > 0 ||
    report.cards.listed.length > 0
  )
}

/** One listed card's line: where it is, which change and run, when it was written. */
export function cardLine(card) {
  return `${card.path} · ${card.change} · run ${card.runId} · written ${card.writtenAt || 'at an unknown time'}`
}

/** The listed cards, newest written first; equal or unknown times keep the listing's order. */
export function orderCards(report) {
  const at = c => {
    const t = Date.parse(c.writtenAt)
    return Number.isNaN(t) ? -Infinity : t
  }
  return report.cards.listed
    .map((card, i) => ({ card, i }))
    .sort((a, b) => at(b.card) - at(a.card) || a.i - b.i)
    .map(x => x.card)
}

const writtenLine = report => `preflight written ${report.writtenAt || 'at an unknown time'}`

/**
 * The band's lines, in order (design D6): the message's first line, each
 * `fail` or `warn` check in the doctor's words, each spoken note's banner,
 * each card with the command that shows it, and when the report was written.
 * Empty when there is nothing to say.
 */
export function bandLines(report) {
  if (!shouldDraw(report)) return []
  const lines = []
  const first = (report.message || '').split('\n')[0]
  if (first) lines.push(first)
  for (const c of flagged(report)) lines.push(`${c.status} ${c.id}: ${c.detail}`)
  for (const n of report.notes.spoken) lines.push(n.banner)
  for (const card of orderCards(report)) lines.push(`${cardLine(card)} — /interlock-handoff`)
  lines.push(`${writtenLine(report)} · /interlock-preflight`)
  return lines
}

/**
 * The `/interlock-preflight` pane's lines: the message verbatim, every check
 * with its fix lines indented as the hook prints them, the notes spoken at
 * this session start with each root's mark, the cards and what was not
 * listed, and every note and card the hook could not read. No empty line.
 */
export function preflightPaneLines(report) {
  const lines = []
  for (const line of (report.message || '').split('\n')) if (line) lines.push(line)
  lines.push(writtenLine(report))

  lines.push(report.doctor.ran ? (report.doctor.parsed ? 'checks' : 'checks: the doctor ran and its output could not be parsed') : 'checks: the doctor did not run')
  for (const c of report.doctor.checks) {
    lines.push(`${c.status} ${c.id}: ${c.detail}`)
    if (c.fix) {
      const [first, ...rest] = c.fix.split('\n')
      lines.push(`     fix: ${first}`)
      for (const more of rest) if (more.trim()) lines.push(`          ${more.trim()}`)
    }
  }

  lines.push(report.notes.spoken.length ? 'interrupted runs spoken at this session start' : 'no interrupted run was spoken at this session start')
  for (const n of report.notes.spoken) {
    lines.push(n.banner)
    for (const m of n.marks) lines.push(m.marked ? `  marked · ${m.root}` : `  not marked: ${m.reason || 'no reason given'}`)
  }
  for (const u of report.notes.unreadable) lines.push(`note unreadable: ${u.file}: ${u.reason}`)

  const ordered = orderCards(report)
  lines.push(ordered.length ? 'halt resume cards — /interlock-handoff' : 'no halt resume card is on disk for an open change')
  for (const card of ordered) lines.push(cardLine(card))
  if (report.cards.archived) lines.push(`${report.cards.archived} card(s) of archived changes not listed`)
  for (const u of report.cards.unreadable) lines.push(`card unreadable: ${u.path}: ${u.reason}`)
  for (const dir of report.cards.lookedIn) lines.push(`looked in: ${dir}`)
  return lines
}

/** What a pane says with no report held: the file's path and why, or that it has not been read yet. */
export function noReportText(path, problem) {
  return `no preflight report is held for this session start: ${path}: ${problem || 'not read yet'}`
}

/** What the handoff pane says with a report and no card: that, and every directory looked in. */
export function noCardText(report) {
  return ['no halt resume card is on disk for an open change', ...report.cards.lookedIn.map(dir => `looked in: ${dir}`)]
}

// Every control character but tab and newline: the `Markdown` element refuses them.
const CONTROL = /[\u0000-\u0008\u000B-\u001F\u007F-\u009F]/g

/**
 * A card's text as the handoff pane renders it: control characters made
 * spaces, and when longer than `cap`, cut so that the text and a note naming
 * the characters left out and the card's path fit within `cap` (design D7).
 */
export function clampCard(raw, path, cap = LIMITS.handoffPaneChars) {
  const clean = text(raw).replace(CONTROL, ' ')
  if (clean.length <= cap) return { text: clean, cut: 0 }
  const note = n => `\n\n_… ${n} characters left out; the whole card is ${path}_`
  // The note for the whole text is the longest the note can be, so the kept head plus any shorter note still fits.
  let keep = Math.max(0, cap - note(clean.length).length)
  const code = clean.charCodeAt(keep - 1)
  if (keep > 0 && code >= 0xd800 && code <= 0xdbff) keep -= 1
  const cut = clean.length - keep
  return { text: (clean.slice(0, keep) + note(cut)).slice(0, cap), cut }
}

/** What the module holds between reads (design D8): the report or the problem, the hide flag, whether the problem was named. */
export function freshStart() {
  return { report: null, path: null, problem: null, hidden: false, named: false }
}

/**
 * The module's next `start` after a read (design D5, D8), whether the band
 * must be redrawn, and the one debug line to name, if any. A re-read of the
 * report already held changes nothing, hide flag and all. A new report is
 * held, and stays hidden only when it continues a report already held across
 * a compaction. A problem drops the held report, since the file is no longer
 * this session's, and is named once until a report is held again.
 *
 * @param {object} start what `freshStart` returns, as last adopted
 * @param {{report?: object, problem?: string}} outcome `readPreflightReport`'s result, or a read's rejection as a problem
 * @param {string} path the file's path, named on the debug line and the panes
 * @returns {{start: object, changed: boolean, log: string|null}}
 */
export function adoptPreflight(start, outcome, path) {
  const held = start && typeof start === 'object' ? start : freshStart()
  const report = outcome && outcome.report
  if (report) {
    if (held.report && held.report.writtenAt === report.writtenAt && held.report.root === report.root) {
      return { start: held, changed: false, log: null }
    }
    const hidden = held.report !== null && held.hidden && report.source === 'compact'
    return { start: { report, path, problem: null, hidden, named: false }, changed: true, log: null }
  }
  const problem = (outcome && outcome.problem) || 'no report was read'
  const log = held.named ? null : `interlock meter: no preflight report at ${path}: ${problem}`
  const changed = held.report !== null || held.problem !== problem || held.path !== path
  return { start: { report: null, path, problem, hidden: held.hidden, named: true }, changed, log }
}

